import React, { useState } from 'react';
import { Link, useNavigate } from 'react-router-dom';

const ForgetPassForm = () => {
    const [email, setEmail] = useState('');
    const [error, setError] = useState('');
    const [success, setSuccess] = useState('');
    const [password, setPassword] = useState('');
    const navigate=useNavigate();
    const users = localStorage.getItem('users');
    const user = JSON.parse(users).some(user => user.email === email).pop();

    const handleSubmit = (e) => {
        e.preventDefault();

        if (!success) {
            const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;

            if (!emailRegex.test(email) || !user) {
                setError('Please enter a valid email address');
                setSuccess('');
                return;
            }

            setError('');
            // Mock successful email sent
            setSuccess('Reset link sent! Please check your email.');
            setEmail('');
        } else {
            if (password.length === 0) {
                setError('Please enter the verification code');
                return;
            }
            // mock OTP check
            user.password = password;
            <users className="push"></users>
            alert('Password successfully reset!');
            navigate('/');
        }
    };

    return (
        <div className="bg-surface-container-lowest border border-outline-variant p-8 md:p-10 rounded-lg shadow-sm">
            <div className="mb-8 text-center md:text-left">
                <h1 className="font-headline-lg text-headline-lg text-primary mb-2">Reset Password</h1>
                <p className="font-body-md text-body-md text-on-surface-variant">
                    Enter your email address and we'll send you a link to reset your password.
                </p>
            </div>

            <form className="space-y-6" onSubmit={handleSubmit}>
                <div className="space-y-2">
                    <label className="block font-label-md text-label-md text-on-surface" htmlFor="email">Email</label>
                    <div className="relative">
                        <span className="material-symbols-outlined absolute left-3 top-1/2 -translate-y-1/2 text-outline">mail</span>
                        <input
                            className={`w-full h-12 pl-10 pr-4 py-3 bg-white border ${error ? 'border-error focus:border-error focus:ring-error/20' : 'border-outline-variant focus:border-secondary focus:ring-secondary/20'} rounded-lg focus:outline-none focus:ring-2 transition-all font-body-md text-body-md text-on-surface placeholder:text-outline`}
                            id="email"
                            name="email"
                            placeholder="name@company.com"
                            type="email"
                            value={email}
                            onChange={(e) => {
                                setEmail(e.target.value);
                                if (error) setError('');
                            }}
                        />
                    </div>
                    {error && <p className="text-error text-sm mt-1">{error}</p>}
                    {success && <p className="text-green-600 text-sm mt-1">{success}</p>}
                    {success && <div className="space-y-2">
                        <label className="block font-label-md text-label-md text-on-surface" htmlFor="email">Enter Verification Code</label>
                        <div className="relative">
                            <span className="material-symbols-outlined absolute left-3 top-1/2 -translate-y-1/2 text-outline">verified_user</span>
                            <input
                                className={`w-full h-12 pl-10 pr-4 py-3 bg-white border ${error ? 'border-error focus:border-error focus:ring-error/20' : 'border-outline-variant focus:border-secondary focus:ring-secondary/20'} rounded-lg focus:outline-none focus:ring-2 transition-all font-body-md text-body-md text-on-surface placeholder:text-outline`}
                                id="Verification Code"
                                name="Verification Code"
                                placeholder="Enter Verification Code"
                                type="password"
                                value={password}
                                onChange={(e) => {
                                    setPassword(e.target.value);
                                    if (error) setError('');
                                }}
                            />
                        </div>
                    </div>}
                </div>

                <button className={`w-full h-12 bg-secondary text-white font-label-md text-label-md rounded-lg hover:bg-primary-container transition-all active:scale-[0.98] shadow-sm flex items-center justify-center gap-2 ${success ? 'hidden' : 'block'}`} type="submit">
                    <span>Send Reset Link</span>
                    <span className="material-symbols-outlined text-[20px]">arrow_forward</span>
                </button>
                <button className={`w-full h-12 bg-secondary text-white font-label-md text-label-md rounded-lg hover:bg-primary-container transition-all active:scale-[0.98] shadow-sm flex items-center justify-center gap-2 ${success ? 'block' : 'hidden'}`} type="submit">
                    <span>Verify</span>
                    <span className="material-symbols-outlined text-[20px]">arrow_forward</span>
                </button>
            </form>

            <div className="mt-8 text-center">
                <Link className="inline-flex items-center gap-1 font-label-md text-label-md text-secondary hover:underline transition-colors hover:none" to="/">
                    <span>Back to Login</span>
                </Link>
            </div>
        </div>
    );
};

export default ForgetPassForm;
